package com.hostelmanagement.ai;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class AIService { private final ComplaintAnalysisService complaint; private final RestClient client; @Value("${ai.provider.enabled:false}") boolean enabled; @Value("${ai.provider.url:}") String url; @Value("${AI_API_KEY:}") String key; public AIService(ComplaintAnalysisService c){complaint=c;client=RestClient.builder().build();}
 public Map<String,Object> complaint(String text){return new LinkedHashMap<>(complaint.analyze(text));}
 public String chat(String question){ if(!enabled||url==null||url.isBlank()) return "I can help with hostel rules, fees, room information, leave, attendance, complaints, visitors, notices and mess information. Please use the relevant module for hostel-specific records."; try {Map<String,Object> body=Map.of("model",System.getenv().getOrDefault("AI_MODEL","gpt-4.1-mini"),"messages",List.of(Map.of("role","user","content",question))); Map<?,?> res=client.post().uri(url).header("Authorization","Bearer "+key).body(body).retrieve().body(Map.class); return String.valueOf(res.getOrDefault("answer","AI provider response received.")); }catch(Exception e){return "AI provider is unavailable. Please contact the warden/admin for hostel-specific information.";} }
}
